INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('53bfb08f-63b3-4454-88cd-50544ec8d5f2', 'Euripides', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'S/N Euripides', 'ANCLA', 'Sección "B" Centro Norte, Querétaro', 'Querétaro', '76125', 'MX', 'S/N Euripides, ANCLA, Sección "B" Centro Norte, Querétaro, Querétaro 76125', 20.640642108, -100.4046950909, 'Retail', 'Lifestyle Center', 'Sports & Recreation', NULL, NULL, 1827.22, NULL, NULL, '{"map_lease_expiration_date":"2037-01-01","map_marker_color":"#808080","coordinate":"point|20.6406421080|-100.4046950909|accurate","city_state":"Sección \"B\" Centro Norte, Querétaro, Querétaro","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"Avenida Ejército Republicano 300, Interior 7, Carretas, Santiago de Querétaro, Querétaro 76059","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"2042-01-01","lease_expiration_date":"2037-01-01","lease_renewal_notice":"3 Months Prior","lease_length_in_months_remaining":123,"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":61677,"grid_name":"Euripides","grid_full_address":"S/N Euripides, ANCLA, Sección \"B\" Centro Norte, Querétaro, Querétaro 76125","map_addr_1":"S/N Euripides","map_addr_2":"ANCLA","map_city_state_zip":"Sección \"B\" Centro Norte, Querétaro, Querétaro 76125","grid_brand":"Planet Fitness","location_created_at":"2026-01-06 19:23:58","active_lease_count_over_time":55421,"location_count_over_time":61677,"remaining_rent_liability_over_time":55421}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('9a33be56-021f-4d01-9e54-8bc561b85295', '53bfb08f-63b3-4454-88cd-50544ec8d5f2', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Euripides Lease: Desarrollo Habitacional del Centro, S.A. de C.V. (01/02/2027 - 01/01/2037)', NULL, false, 'vencido', 'Lease', NULL, '2027-06-02', '2027-01-02', '2037-01-01', '2047-01-01', false, 2, NULL, 2, NULL, NULL, '2036-10-01', 'Send Notice to Renew', 119, 'Desarrollo Habitacional del Centro, S.A. de C.V.', NULL, NULL, 'Avenida Ejército Republicano 300', 'Interior 7', 'Carretas, Santiago de Querétaro', 'Querétaro', '76059', 'MX', 'J. Natividad de Jesús Martinez', NULL, 'eparra@gonie.com.mx', 152, 'percent', NULL, NULL, 1279054, E'1. El primer pago equivalente a una mensualidad por la cantidad de $319,763.50 (Trescientos diecinueve mil setecientos sesenta y tres pesos 50/100 M.N.) más IVA, se realizará dentro de los 30 (treinta) días naturales siguientes a la fecha de firma de este instrumento; \n2. El segundo pago equivalente a una mensualidad, esto es, la cantidad de $$319,763.50 (Trescientos diecinueve mil setecientos sesenta y tres pesos 50/100 M.N.) más IVA se realizará dentro de los 30 (treinta) días naturales siguientes a la fecha de la entrega de la licencia de construcción por parte del Arrendador. \n3. El tercer pago equivalente a dos mensualidades, es decir, la cantidad de $639,527.00 (Seiscientos treinta y nueve mil quinientos veintisiete pesos 00/100 M.N.) más el IVA, dentro de los 30 (treinta) días naturales siguientes a la fecha de la entrega física del Local Comercial.\n\nLas Partes acuerdan que las mensualidades adelantadas, serán tomadas y aplicadas después del periodo de gracia, de la siguiente forma: La primera de ellas, se tomará en cuenta en el mes 8 (ocho) de vigencia del contrato, el segundo de ellos se tomará en cuenta en el mes 11 (once), el tercero se tomará en cuenta para el mes 14 (catorce) y el último de ellos (incluido en el tercer pago) en el mes 17 (diecisiete) de vigencia de este instrumento. Sin perjuicio de los pagos adelantados establecidos con antelación, la Arrendataria se obliga a pagar a la Arrendadora, sin que medie requerimiento alguno, de manera mensual durante la vigencia del presente contrato el importe establecido en el numeral 11 de la "Caratula" del presente contrato por concepto de renta.', 7994087.5, false, '{"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('9a33be56-021f-4d01-9e54-8bc561b85295', 'Fecha de Firma del Contrato', '01 de diciembre de 2025', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('9a33be56-021f-4d01-9e54-8bc561b85295', 'Domicilio del Contrato', E'Eurípides S/N, Sección "B" Centro Norte, Municipio de Querétaro, Estado de Querétaro, C.P. 76125.\nLocal ANCLA', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('9a33be56-021f-4d01-9e54-8bc561b85295', 'Late Fees', '17', '17', 'INTERESES MORATORIOS', E'- La tasa de interés por pagos atrasados es del 2% mensual.\n- Se aplica sobre el total adeudado si el pago se retrasa más de 20 días naturales.\n- El interés se calcula cada mes o parte de mes mientras dure el retraso.\n- No se aplican intereses si el retraso es culpa de la Arrendadora, como no entregar el comprobante fiscal.', 'La tasa de intereses moratorios será del 2% (dos por ciento) mensual. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago por más de 20 (veinte) días naturales de la fecha en que debió hacerlo. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación de este. Los intereses moratorios, no serán aplicables, si el retraso es por causa de la Arrendadora en la entrega del comprobante fiscal y/o alguna otra razón imputable a ésta.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('9a33be56-021f-4d01-9e54-8bc561b85295', 'Common Area Maintenance Charges', '11', '10 A)', 'GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', '- The parties agree that the costs for administration and maintenance are included in the monthly rent payment.', 'Las Partes acuerdan que los gastos de Administración y Mantenimiento vienen incluidos dentro del monto que paga por concepto de arrendamiento mensual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('9a33be56-021f-4d01-9e54-8bc561b85295', 'Incremento de Renta', '7', '6', 'AJUSTE Y/O INCREMENTO DE LA RENTA', E'- The monthly rent will increase in month 25 and then every 12 months.\n- The increase starts from June 2, 2027, or the store''s opening date, whichever comes first.\n- Rent remains unchanged from month 13 to month 24.\n- From month 25, rent adjusts automatically each year based on the previous year''s INPC percentage change.\n- If the lease is renewed for another five years, rent will continue to adjust annually based on the INPC percentage change, with no exceptions or grace periods.', E'Las Partes convienen que la Renta Mensual será incrementada en el mes 25 y posteriormente cada 12 (doce) meses, contado a partir del 2 de junio de 2027 o a la fecha de apertura del local, lo que ocurra primero, incrementándose de acuerdo con la siguiente mecânica:\n\nLas partes acuerdan que el monto de la renta mensual permanecerá sin ajuste durante el periodo comprendido entre el mes 13 trece y el mes 24 veinticuatro de vigencia del presente contrato.\n\nA partir del mes 25 veinticinco, la renta se ajustará anualmente, es decir cada 12 meses del mes calendario del contrato y de manera automática, conforme a la variación porcentual que haya experimentado el INPC en el periodo inmediato anterior,\n\nEn caso de que las partes ejerzan la opción de renovación por un segundo periodo forzoso de cinco años, la renta mensual se ajustará anualmente, cada 12 doce meses del mes calendario del contrato, desde el inicio de dicho periodo, conforme a la variación porcentual anual del INPC publicada por el INEGI, sin excepción o periodo de gracia alguno.');
