INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('8a4b8f05-d40c-4ef3-a8a9-46e541454616', 'Bosque Urbano', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '2940 Gobernador Curiel', 'E-106', 'Tlaquepaque', 'Jalisco', '45599', 'MX', '2940 Gobernador Curiel, E-106, Tlaquepaque, Jalisco 45599', 20.59802, -103.344962, 'Retail', 'Lifestyle Center', 'Sports & Recreation', NULL, 'ARVO Guadalajara', 2000, NULL, NULL, '{"coordinate":"rooftop|20.5980200000|-103.3449620000|accurate","city_state":"Tlaquepaque, Jalisco","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"Blvd. Adolfo López Mateos No. 216 int. 223, Col. San Pedro de los Pinos, Álvaro Obregón,, Ciudad de México, Ciudad de México 01180","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"TBD","lease_expiration_date":"TBD","lease_renewal_notice":"180 Days Prior","lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":67829,"grid_name":"Bosque Urbano","grid_full_address":"2940 Gobernador Curiel, E-106, Tlaquepaque, Jalisco 45599","map_addr_1":"2940 Gobernador Curiel","map_addr_2":"E-106","map_city_state_zip":"Tlaquepaque, Jalisco 45599","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2026-05-26 18:27:52","active_lease_count_over_time":61275,"location_count_over_time":67829,"remaining_rent_liability_over_time":61275}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('8c8093d0-acc7-4c8e-987d-258ab84455dd', '8a4b8f05-d40c-4ef3-a8a9-46e541454616', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Bosque Urbano Lease: CAABSA Constructora, S.A. de C.V.', NULL, false, 'activo', 'Lease', NULL, NULL, NULL, NULL, NULL, false, 2, NULL, 0, NULL, NULL, NULL, 'Send Notice to Renew', NULL, 'CAABSA Constructora, S.A. de C.V.', NULL, NULL, 'Blvd. Adolfo López Mateos No. 216 int. 223, Col. San Pedro de los Pinos, Álvaro Obregón,', NULL, 'Ciudad de México', 'Ciudad de México', '01180', 'MX', 'Maria Cecilia Quintanilla Madero', NULL, 'smadrazo@caabsa.com.mx | anieto@caabsa.com.mx', 150, NULL, NULL, 400000, 800000, 'EI ARRENDATARIO se obliga a pagar al ARRENDADOR en la fecha de firma del presente, la cantidad de $800,000.00 (ochocientos mil Pesos 00/100, M.N.) equivalente a 2 (dos) meses de la Renta Fija, la cual se aplicará, bajo el mismo concepto, para el primer mes de Renta Fija. En caso de incumplimiento por parte del ARRENDATARIO el pago a que se refiere este párrafo, el ARRENDADOR, a su libre elección, podrá rescindir este contrato, mediante aviso por escrito al ARRENDATARIO, sin necesidad de resolución judicial al respecto.', NULL, true, '{"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"is_next_percent_rent_payment":"No","rent_commencement_date_original":"TBD","expiration_date_original":"TBD","expiration_date_including_options_original":"TBD"}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('8c8093d0-acc7-4c8e-987d-258ab84455dd', 'Fecha de Firma del Contrato', '17 de febrero de 2026', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('8c8093d0-acc7-4c8e-987d-258ab84455dd', 'Domicilio del Contrato', E'Inmueble identificado como Fracción 1 resultante de la subdivisión del predio denominado "El Deán" o "San Nicolás de las Higuerillas", en la ciudad de Guadalajara, Jalisco con el número oficial 2940 de la Avenida Luis Gobernador Curiel y Avenida 18 de marzo número 71 Código Postal 44470\nLocal Comercial E-106', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('8c8093d0-acc7-4c8e-987d-258ab84455dd', 'Common Area Maintenance Charges', '7', 'Clausula Septima', 'CUOTA DE MANTENIMIENTO', E'- The tenant must pay a maintenance fee to the landlord or a designated person within the first 10 business days of each month.\n- This fee is 10% of the fixed rent plus applicable taxes.\n- Paying this fee does not give the tenant any rights to make decisions about or request information on the maintenance of the shopping center.', E'Además de la Renta fija vigente y la Renta Variable, el ARRENDATARIO se obliga a pagar al ARRENDADOR o a la persona que esta última designe por escrito, dentro de los 10 (diez) primeros días hábiles de cada mes, por concepto de cuota de mantenimiento y operación de las áreas y bienes de uso común del Centro Comercial, una cantidad equivalente al 10% (Diez por ciento) de la Renta Fija más el impuesto al valor agregado correspondiente (en lo sucesivo ''Cuota de Mantenimiento'')\n\nEl pago de la cuota prevista en esta cláusula no dará derecho alguno al ARRENDATARIO, por ningún concepto y bajo ninguna circunstancia, para decidir ni intervenir o participar en la toma de decisiones sobre el tipo y alcances del mantenimiento que se deba dar al Centro Comercial, ni para solicitar al ARRENDADOR o al administrador del Centro Comercial información o rendición de cuentas sobre el destino de la cuota de mantenimiento pagada por los arrendatarios del Centro Comercial.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('8c8093d0-acc7-4c8e-987d-258ab84455dd', 'Incremento de Renta', '7', 'Clausula Sexta', 'INCREMENTOS', E'- The fixed rent will increase annually.\n- The increase will match the percentage change in the National Consumer Price Index published in the Official Gazette over the previous 12 months.\n- The first rent increase will occur 12 months after the commercial space is delivered.', E'Las Partes están de acuerdo en que la Renta Fija pactada se incrementarà en forma anual, aplicándose a la última Renta Fija vigente el mismo porcentaje de incremento que el que haya sufrido el Indice Nacional de Precios al Consumidor que se publica en el Diario Oficial de la Federación durante los 12 (doce) meses anteriores al mes en que se incremente la Renta Fija.\n\nEl primer incremento a la Renta Fija se realizará a los 12 (doce) meses siguientes contados a partir de la Fecha Entrega del Local Comercial.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('8c8093d0-acc7-4c8e-987d-258ab84455dd', 'Late Fees', '18', 'Clausula Decima Octava', 'INTERESES MORATORIOS', E'- If the tenant fails to meet any financial obligation in the contract, they must pay a daily late interest for each day of delay.\n- The interest rate is based on the 28-day Interbank Equilibrium Interest Rate published by the Bank of Mexico, plus 2%.\n- If the rate is not published on the day the default begins, the last published rate will be used.\n- The landlord is not required to accept a monthly payment if previous payments are not settled.\n- Payments made by the tenant will first cover unpaid interest, maintenance costs, and utility expenses (water, electricity, gas, phone).\n- Payments will also cover any penalties outlined in the contract before being applied to rent, starting with the oldest dues.', E'En caso de incumplimiento de cualquier obligación de carácter económico estipulada en este Contrato, el ARRENDATARIO deberá cubrir un interés moratorio calculado diariamente por cada día de retraso, equivalente a aplicar el monto de la obligación incumplida, la Tasa de Interés lnterbancaria de Equilibrio a plazo de 28 días, que publique el Banco de México en el Diario Oficial de la Federación, el día en que inicie el incumplimiento, más por 2.\n\nSi el día en que inicie el incumplimiento no se publicará dicha tasa, se tomará la última tasa que se hubiere publicado previa a dicho día. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente.\n\nEl ARRENDADOR no estará obligada a recibir el pago de una mensualidad si no están cubiertas las anteriores y, en cualquier caso, las cantidades pagadas a cuenta por el ARRENDATARIO se aplicarán en primer lugar a intereses vencidos y no pagados, a los gastos mantenimiento, así como los correspondientes a la publicidad, suministro de agua, electricidad, gas, teléfono y, en general, a cualquier otro gasto a cargo del ARRENDATARIO, incluyendo las penas convencionales estipuladas en este contrato y, por último, al pago de rentas, comenzando por las más antiguas.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('8c8093d0-acc7-4c8e-987d-258ab84455dd', 'Pago de Rentas', '6', 'Clausula Cuarta 4.1', 'RENTA FIJA', E'- The monthly rent is $400,000.00 plus applicable VAT.\n- This amount is calculated by multiplying $200.00 by 2,000 square meters of the commercial space.\n- Rent payments start after the grace period ends or when the commercial space opens to the public, whichever comes first.\n- Rent is paid in advance via deposit or electronic transfer to the bank account specified in Clause Five of the contract.\n- Payments must be made within the first 10 calendar days of each month.\n- The rent will increase annually as agreed in the contract.', E'4.1. Renta Fija\nLa cantidad mensual de $400,000.00, más IVA correspondiente o cualquier otro que lo sustituya o fuese aplicable, calculada en razón de multiplicar la cantidad de $200.00 por 2,000.00 m2 de superficie del Local Comercial, renta que se pagará a partir del\ntérmino de su Periodo de Gracia o bien o de la fecha de apertura al público del Local Comercial, lo que suceda primero.\n\nEl importe de la Renta Fija señalada en el párrafo inmediato anterior (en lo sucesivo la "Renta Fija") se pagará mediante depósito o transferencia electrónica a la cuenta bancaria señalada en la Cláusula Quinta del presente Contrato, por mensualidades adelantadas, dentro de los primeros 10 días naturales de cada mes y se incrementará anualmente, en los términos pactados en presente contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('8c8093d0-acc7-4c8e-987d-258ab84455dd', 'Percentage Rent', '6', 'Cláusula Cuarta 4.3', 'RENTA VARIABLE', E'- Each month, the landlord will compare the fixed rent with 8% of the total net sales from the previous month.\n- If 8% of the sales is higher than the fixed rent, the tenant must pay the difference plus applicable taxes.\n- This additional amount, called "Variable Rent," is due within the first 10 days of the following month.\n- Payments should be made via deposit or electronic transfer to the bank accounts specified in Clause Five.', 'Adicionalmente a la Renta Fija, durante los primeros 10 (diez) días naturales de cada mes, el ARRENDADOR comparará el importe de la Renta Fija correspondiente al mes inmediato anterior, con el importe que resulte de aplicar el 8% (ocho por ciento) al importe total de las ventas netas realizadas en el Local Comercial durante dicho mes inmediato anterior. En caso, de que el 8% (ocho por ciento) que se aplique sobre el total de las ventas realizadas en el Local Comercial durante el mes que corresponda, sea superior a la Renta Fija, el ARRENDATARIO se obliga a pagar al ARRENDADOR la diferencia obtenida, más el impuesto al valor agregado correspondiente (en lo sucesivo la "Renta Variable"),; diferencias que se pagarán mensualmente, mediante depósito o transferencia electrónica en las cuentas bancarias señaladas en la Cláusula Quinta durante los primeros 10 (diez) días naturales del mes inmediato siguiente a aquel al que corresponda el pago.');
